            p.addCurve(to: CGPoint(x: 11, y: 19.298), control1: CGPoint(x: 10.8341, y: 19.8478), control2: CGPoint(x: 11.0055, y: 19.5859))
            p.closeSubpath()
            p.move(to: CGPoint(x: 16.5, y: 14.5))
            p.addLine(to: CGPoint(x: 21.5, y: 9.5))
            p.move(to: CGPoint(x: 16.5, y: 9.5))
            p.addLine(to: CGPoint(x: 21.5, y: 14.5))
        case .x:
            p.move(to: CGPoint(x: 18, y: 6))
            p.addLine(to: CGPoint(x: 6, y: 18))
            p.move(to: CGPoint(x: 6, y: 6))
            p.addLine(to: CGPoint(x: 18, y: 18))
        case .zoomIn:
            p.addEllipse(in: CGRect(x: 3, y: 3, width: 16, height: 16))
            p.move(to: CGPoint(x: 21, y: 21))
            p.addLine(to: CGPoint(x: 16.65, y: 16.65))
            p.move(to: CGPoint(x: 11, y: 8))
            p.addLine(to: CGPoint(x: 11, y: 14))
            p.move(to: CGPoint(x: 8, y: 11))
            p.addLine(to: CGPoint(x: 14, y: 11))
        }
        return p
    }
}
